require_once dirname(__DIR__).'/cms/layout.php';$user=require_super();$rows=db()->query('SELECT a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 500')->fetchAll();admin_header('审计日志',$user);?><section class="panel"><div class="panel-head"><div><h2>最近 500 条操作</h2><small>记录登录、内容、账号与删除操作；IP 仅保存不可逆摘要。</small></div></div><div class="table-wrap"><table><thead><tr><th>UTC 时间</th><th>操作人</th><th>动作</th><th>对象</th><th>详情</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['created_at'])?></td><td><?=e($row['username']?:'未登录访客')?></td><td><?=e($row['action'])?></td><td><?=e($row['entity_type'])?> #<?=e((string)$row['entity_id'])?></td><td><div class="audit-detail"><?=e($row['details_json'])?></div></td></tr><?php endforeach;?></tbody></table></div></section><?php admin_footer();
